@@ -2311,1 +2311,1 @@
-static bool is_vector_scalar_bitwise_pattern(Node* n, Node* m) {
+static bool is_vector_scalar_binary_pattern(Node* n, Node* m) {
@@ -2353,0 +2353,16 @@
+// 'n' is the current user of input 'm', which is being considered for cloning.
+// Other users must also allow cloning to avoid matching 'm' both folded and standalone.
+static bool are_users_clone_compatible(Node* n, Node* m) {
+  for (DUIterator_Fast imax, i = m->fast_outs(imax); i < imax; i++) {
+    Node* use = m->fast_out(i);
+    if (use == n) {
+      continue;
+    }
+    if (!is_vector_bitwise_not_pattern(use, m) &&
+        !is_vector_scalar_binary_pattern(use, m)) {
+      return false;
+    }
+  }
+  return true;
+}
